import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  FaArrowLeft, 
  FaShoppingCart, 
  FaStar, 
  FaHeart,
  FaSearch,
  FaFilter
} from 'react-icons/fa';
import './TribalProducts.css';

// Tribal Products data
const products = [
  {
    id: 1,
    name: 'Toda Embroidery Shawl',
    category: 'Textiles',
    price: 2499,
    mrp: 2999,
    rating: 4.8,
    reviews: 124,
    image: 'https://images.unsplash.com/photo-1601924994987-69e26d50dc26?w=500',
    description: 'Handcrafted traditional Toda embroidery shawl with red and black patterns',
    tribe: 'Toda',
    inStock: true
  },
  {
    id: 2,
    name: 'Nilgiri Wild Forest Honey',
    category: 'Food & Beverages',
    price: 599,
    mrp: 699,
    rating: 4.9,
    reviews: 256,
    image: 'https://images.unsplash.com/photo-1587049352846-4a222e784d38?w=500',
    description: 'Pure, raw forest honey collected by Kurumba honey hunters',
    tribe: 'Kurumba',
    inStock: true
  },
  {
    id: 3,
    name: 'Kota Handmade Pottery Set',
    category: 'Handicrafts',
    price: 1899,
    mrp: 2200,
    rating: 4.7,
    reviews: 89,
    image: 'https://images.unsplash.com/photo-1610701596007-11502861dcfa?w=500',
    description: 'Traditional Kota pottery set, handcrafted by skilled artisans',
    tribe: 'Kota',
    inStock: true
  },
  {
    id: 4,
    name: 'Tribal Wall Painting',
    category: 'Art & Paintings',
    price: 3499,
    mrp: 4000,
    rating: 4.6,
    reviews: 67,
    image: 'https://images.unsplash.com/photo-1549490349-8643362247b5?w=500',
    description: 'Original Nilgiri tribal art painting on canvas',
    tribe: 'Toda',
    inStock: true
  },
  {
    id: 5,
    name: 'Bamboo Basket - Traditional',
    category: 'Handicrafts',
    price: 799,
    mrp: 950,
    rating: 4.5,
    reviews: 143,
    image: 'https://images.unsplash.com/photo-1606760227091-3dd870d97f1d?w=500',
    description: 'Eco-friendly handwoven bamboo basket by tribal artisans',
    tribe: 'Kurumba',
    inStock: true
  },
  {
    id: 6,
    name: 'Nilgiri Tea Gift Box',
    category: 'Food & Beverages',
    price: 899,
    mrp: 1100,
    rating: 4.8,
    reviews: 312,
    image: 'https://images.unsplash.com/photo-1594631252845-29fc4cc8cde9?w=500',
    description: 'Premium organic Nilgiri tea collection - 4 varieties',
    tribe: 'Badaga',
    inStock: true
  },
  {
    id: 7,
    name: 'Irula Herbal Medicine Kit',
    category: 'Wellness',
    price: 1299,
    mrp: 1500,
    rating: 4.6,
    reviews: 78,
    image: 'https://images.unsplash.com/photo-1471193945509-9ad0617afabf?w=500',
    description: 'Traditional herbal remedies prepared using forest herbs',
    tribe: 'Irula',
    inStock: true
  },
  {
    id: 8,
    name: 'Handwoven Tribal Bag',
    category: 'Textiles',
    price: 1499,
    mrp: 1800,
    rating: 4.7,
    reviews: 95,
    image: 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=500',
    description: 'Colorful handwoven bag with traditional tribal motifs',
    tribe: 'Paniya',
    inStock: true
  }
];

const categories = ['All', 'Textiles', 'Handicrafts', 'Food & Beverages', 'Art & Paintings', 'Wellness'];

function TribalProducts() {
  const navigate = useNavigate();
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);

  const filteredProducts = products.filter(product => {
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         product.tribe.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const addToCart = (product) => {
    setCart([...cart, product]);
    alert(`${product.name} added to cart!`);
  };

  const toggleFavorite = (productId) => {
    setFavorites(prev => 
      prev.includes(productId) 
        ? prev.filter(id => id !== productId)
        : [...prev, productId]
    );
  };

  const discount = (price, mrp) => Math.round(((mrp - price) / mrp) * 100);

  return (
    <div className="tribal-products-container">
      {/* Header */}
      <motion.header
        className="products-header"
        initial={{ y: -50 }}
        animate={{ y: 0 }}
      >
        <button className="back-btn" onClick={() => navigate('/')}>
          <FaArrowLeft /> Back
        </button>
        <h1>🛍️ Tribal Products Store</h1>
        <div className="cart-button">
          <FaShoppingCart size={24} />
          {cart.length > 0 && <span className="cart-badge">{cart.length}</span>}
        </div>
      </motion.header>

      {/* Main Content */}
      <main className="products-main">
        <motion.div
          className="store-banner"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <h2>🌿 Authentic Tribal Products</h2>
          <p>Support indigenous artisans • Handcrafted with love • Direct from Nilgiris</p>
        </motion.div>

        {/* Search and Filter */}
        <div className="products-controls">
          <div className="search-box">
            <FaSearch />
            <input
              type="text"
              placeholder="Search products or tribes..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="category-filter">
            <FaFilter />
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
            >
              {categories.map(category => (
                <option key={category} value={category}>{category}</option>
              ))}
            </select>
          </div>
        </div>

        {/* Products Grid */}
        <div className="products-grid">
          {filteredProducts.map((product, index) => (
            <motion.div
              key={product.id}
              className="product-card"
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              whileHover={{ y: -10 }}
            >
              <div className="product-image-wrapper">
                <img src={product.image} alt={product.name} className="product-image" />
                <div className="discount-badge">{discount(product.price, product.mrp)}% OFF</div>
                <button
                  className={`favorite-btn ${favorites.includes(product.id) ? 'active' : ''}`}
                  onClick={() => toggleFavorite(product.id)}
                >
                  <FaHeart />
                </button>
              </div>

              <div className="product-content">
                <span className="product-tribe">Made by {product.tribe} Tribe</span>
                <h3 className="product-name">{product.name}</h3>
                <p className="product-description">{product.description}</p>

                <div className="product-rating">
                  <span className="rating-badge"><FaStar /> {product.rating}</span>
                  <span className="reviews">({product.reviews} reviews)</span>
                </div>

                <div className="product-price">
                  <span className="current-price">₹{product.price.toLocaleString()}</span>
                  <span className="mrp">MRP ₹{product.mrp.toLocaleString()}</span>
                </div>

                <div className="stock-status">✓ In Stock</div>

                <button
                  className="add-cart-btn"
                  onClick={() => addToCart(product)}
                >
                  <FaShoppingCart /> Add to Cart
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {filteredProducts.length === 0 && (
          <div className="no-products">
            <p>No products found. Try a different search or category.</p>
          </div>
        )}
      </main>
    </div>
  );
}

export default TribalProducts;
